def find_rectangles(grid):
    """Find rectangular regions of uniform non-background color."""
    rectangles = []
    color_counts = {}

    # Count color frequencies
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            color_counts[color] = color_counts.get(color, 0) + 1

    most_common = sorted(color_counts.items(), key=lambda x: -x[1])[0]
    background = most_common[0][0]

    print(f"Background color: {background}")

    # Find maximal rectangles of single color
    visited = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r, c) in visited:
                continue
            if grid[r][c] == background:
                continue

            color = grid[r][c]
            rect = []
            height, width = 1, 1

            # Find the size of the rectangle starting at (r,c)
            while r + height < len(grid) and grid[r + height][c] == color:
                height += 1
            while c + width < len(grid[0]) and grid[r][c + width] == color:
                width += 1

            # Check if this is a rectangular block (all cells in the block have the color)
            is_rect = True
            for dr in range(height):
                for dc in range(width):
                    if grid[r + dr][c + dc] != color:
                        is_rect = False
                        break
                if not is_rect:
                    break

            if is_rect:
                rect = [(r + dr, c + dc) for dr in range(height) for dc in range(width)]
                rect.sort()
                if rect not in rectangles:
                    rectangles.append(rect)

            visited.add((r, c))

    return rectangles, background

