def find_perfect_rectangles(grid, background):
    """Find all maximal perfect rectangles of non-background colors"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    found = []
    visited_cells = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background or (r, c) in visited_cells:
                continue

            color = grid[r][c]

            # BFS to find connected component of this color
            q = deque([(r, c)])
            comp = set([(r, c)])
            visited = { (r, c) }

            while q:
                cr, cc = q.popleft()
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == color:
                        visited.add((nr, nc))
                        comp.add((nr, nc))
                        q.append((nr, nc))

            # Check if this component forms a perfect rectangle
            r_min, c_min = min(r for r, c in comp), min(c for r, c in comp)
            r_max, c_max = max(r for r, c in comp), max(c for r, c in comp)
            bbox_size = (r_max - r_min + 1) * (c_max - c_min + 1)

            if len(comp) == bbox_size:
                found.append({
                    'color': color,
                    'bbox': (r_min, c_min, r_max, c_max),
                    'dims': (r_max - r_min + 1, c_max - c_min + 1),
                    'size': len(comp)
                })
                visited_cells.update(comp)

    # Sort by size desc
    found.sort(key=lambda x: x['size'], reverse=True)
    return found

def transform(grid, background=3):
    """Fill perfect rectangles with dims >= 5x5 with color 4"""
    new_grid = [list(row) for row in grid]

    rects = find_perfect_rectangles(grid, background)
    for rect in rects:
        if rect['dims'][0] >= 5 and rect['dims'][1] >= 5:
            color = rect['color']
            r_min, c_min, r_max, c_max = rect['bbox']
            for r in range(r_min, r_max + 1):
                for c in range(c_min, c_max + 1):
                    new_grid[r][c] = 4

    return new_grid

